const row = $json ?? {};

const missionId = String(row.mission_id ?? '').trim();
if (!missionId) {
  throw new Error('Mission not found: Data Table returned no mission_id.');
}

const enabled = row.enabled === true || String(row.enabled ?? '').toLowerCase() === 'true';
if (!enabled) {
  throw new Error(`Mission '${missionId}' is disabled.`);
}

function parseJsonArray(value, fieldName) {
  if (Array.isArray(value)) return value;
  const text = String(value ?? '').trim();
  if (!text) return [];
  try {
    const parsed = JSON.parse(text);
    if (!Array.isArray(parsed)) throw new Error(`${fieldName} must be a JSON array.`);
    return parsed.map(String);
  } catch (error) {
    throw new Error(`Invalid ${fieldName} for mission '${missionId}': ${error.message}`);
  }
}

const objective = String(row.objective ?? '').trim();
if (!objective) {
  throw new Error(`Mission '${missionId}' has empty objective.`);
}

const rules = parseJsonArray(row.rules_json, 'rules_json');
const acceptance = parseJsonArray(row.acceptance_criteria_json, 'acceptance_criteria_json');

const originalGoal = [
  `MISSION: ${String(row.name ?? missionId).trim()}`,
  '',
  'OBJECTIVE:',
  objective,
  '',
  'RULES:',
  rules.length ? rules.map((x, i) => `${i + 1}. ${x}`).join('\\n') : '(none)',
  '',
  'ACCEPTANCE CRITERIA:',
  acceptance.length ? acceptance.map((x, i) => `${i + 1}. ${x}`).join('\\n') : '(none)'
].join('\\n');

return [{ json: {
  mission_id: missionId,
  mission_version: Number(row.version ?? 1),
  mission_name: String(row.name ?? missionId),
  mission_enabled: enabled,
  objective,
  rules,
  acceptance_criteria: acceptance,
  original_goal: originalGoal
} }];

const raw = String(
  $json.output ??
  $json.response ??
  $json.content ??
  $json.hermes_output ??
  ''
).trim();

if (!raw) {
  throw new Error('Architect returned empty output.');
}

function extractJsonObject(text) {
  const cleaned = text
    .replace(/```json\s*/gi, '')
    .replace(/```\s*/g, '')
    .trim();

  // 1. Попробовать распарсить весь ответ.
  try {
    return JSON.parse(cleaned);
  } catch (_) {
    // continue
  }

  // 2. Найти JSON object с корректным балансом {}.
  let start = -1;
  let depth = 0;
  let inString = false;
  let escaped = false;

  for (let i = 0; i < cleaned.length; i++) {
    const ch = cleaned[i];

    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (ch === '\\') {
        escaped = true;
      } else if (ch === '"') {
        inString = false;
      }
      continue;
    }

    if (ch === '"') {
      inString = true;
      continue;
    }

    if (ch === '{') {
      if (start === -1) {
        start = i;
      }
      depth++;
      continue;
    }

    if (ch === '}') {
      if (depth > 0) {
        depth--;
      }

      if (depth === 0 && start !== -1) {
        const candidate = cleaned.slice(start, i + 1);

        try {
          return JSON.parse(candidate);
        } catch (_) {
          start = -1;
        }
      }
    }
  }

  throw new Error(
    `Architect returned invalid JSON. Raw output:\n${text}`
  );
}

const plan = extractJsonObject(raw);

if (!plan || typeof plan !== 'object') {
  throw new Error('Architect response is not a JSON object.');
}

if (!Array.isArray(plan.tasks)) {
  throw new Error(
    `Architect response does not contain tasks array. Parsed keys: ${Object.keys(plan).join(', ')}. The Architect must DECOMPOSE the mission into Worker tasks and must not execute or answer the mission directly.`
  );
}

if (plan.tasks.length === 0) {
  throw new Error('Architect returned an empty tasks array.');
}

const maxTasks = Number(
  $('Constants').first().json.max_tasks ?? 20
);

plan.tasks = plan.tasks.slice(0, maxTasks);

for (const task of plan.tasks) {
  if (
    !task ||
    typeof task !== 'object' ||
    !task.id ||
    !task.title ||
    !task.objective ||
    !Array.isArray(task.acceptance_criteria)
  ) {
    throw new Error(
      `Invalid task definition: ${JSON.stringify(task)}`
    );
  }

  if (!Array.isArray(task.verification)) {
    task.verification = [];
  }

  if (!Array.isArray(task.scope)) {
    task.scope = [];
  }

  if (!Array.isArray(task.dependencies)) {
    task.dependencies = [];
  }
}

return [
  {
    json: {
      plan_summary: String(plan.summary ?? ''),
      tasks: plan.tasks,
      task_index: 0,
      task_attempt: 1,
      total_tasks: plan.tasks.length,
      review_feedback: ''
    }
  }
];

const tasks = Array.isArray($json.tasks) ? $json.tasks : [];
const index = Number($json.task_index ?? 0);

if (index >= tasks.length) {
  return [{
    json: {
      ...$json,
      execution_route: 'all_tasks_completed'
    }
  }];
}

const task = tasks[index];
const feedback = String($json.review_feedback ?? '');

const workerPrompt = [
  $('Prompt Templates').first().json.worker_prompt,
  '',
  `TASK ${task.id}: ${task.title}`,
  '',
  'OBJECTIVE:',
  task.objective,
  '',
  'ACCEPTANCE CRITERIA:',
  task.acceptance_criteria
    .map((x, i) => `${i + 1}. ${x}`)
    .join('\n'),
  '',
  'VERIFICATION:',
  task.verification.join('\n'),
  '',
  'SCOPE:',
  task.scope.join('\n'),
  '',
  feedback ? 'PREVIOUS REVIEW FEEDBACK:' : '',
  feedback
].filter(Boolean).join('\n');

return [{
  json: {
    ...$json,
    execution_route: 'run_task',
    current_task: task,
    current_task_id: task.id,
    worker_prompt: workerPrompt
  }
}];

const status=String($json.worker_status??'').toLowerCase(); 
const route=String($json.worker_route??'').toLowerCase(); 
return [{json:{...$json,
               worker_status:status,
               worker_route:route,
               worker_output:String($json.output??''),
               worker_poll_count:Number($json.poll_count??0),
               worker_run_not_found:Boolean($json.run_not_found??false),
               http_error_code:$json.http_code??null,
               hermes_error:String($json.error??''),
               transient_error:route==='transient_error'}}];

function unwrap(value) { const x = value?.json ?? value?.data ?? value ?? {}; return x && typeof x === 'object' && !Array.isArray(x) ? x : {}; }
const result = unwrap($json);
const status = String(
  $json.status ??
  $json.reviewer_status ??
  ''
).toLowerCase();

const route = String(
  $json.reviewer_route ??
  $json.route ??
  (status === 'completed' ? 'completed' : '')
).toLowerCase();
return [{json:{...result,
               reviewer_status:status,
               reviewer_route:route,
               reviewer_output: String(
  result.output ??
  result.reviewer_output ??
  result.response ??
  result.content ??
  ''
),
               reviewer_poll_count:Number(result.poll_count??0),
               reviewer_run_not_found:Boolean(result.run_not_found??false),
               http_error_code:result.http_code??null,hermes_error:String(result.error??''),
               transient_error:route==='transient_error'}}];

const raw = String(
  $json.output ??
  $json.reviewer_output ??
  $json.response ??
  $json.content ??
  $json.hermes_output ??
  ''
).trim();

if (!raw) {
  throw new Error('Reviewer returned empty output');
}

let text = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

function extractReviewObject(input) {
  const candidates = [];
  let start = -1;
  let depth = 0;
  let inString = false;
  let escaped = false;

  for (let i = 0; i < input.length; i++) {
    const ch = input[i];

    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (ch === '\\') {
        escaped = true;
      } else if (ch === '"') {
        inString = false;
      }
      continue;
    }

    if (ch === '"') {
      inString = true;
      continue;
    }

    if (ch === '{') {
      if (depth === 0) start = i;
      depth++;
      continue;
    }

    if (ch === '}') {
      if (depth === 0) continue;
      depth--;
      if (depth === 0 && start !== -1) {
        const candidate = input.slice(start, i + 1);
        try {
          const parsed = JSON.parse(candidate);
          if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
            candidates.push(parsed);
          }
        } catch (_) {
          // Ignore malformed object candidates and continue scanning.
        }
        start = -1;
      }
    }
  }

  const review = candidates.find(candidate => {
    const status = String(candidate.status ?? '').toLowerCase();
    const score = Number(candidate.score);
    return (
      ['pass', 'needs_changes'].includes(status) &&
      Number.isFinite(score) &&
      score >= 0 && score <= 100 &&
      Object.prototype.hasOwnProperty.call(candidate, 'reason') &&
      Object.prototype.hasOwnProperty.call(candidate, 'next_task')
    );
  });

  if (!review) {
    throw new Error(
      'Reviewer output does not contain a valid review JSON object. ' +
      'Expected status, score, reason and next_task.'
    );
  }

  return review;
}

const review = extractReviewObject(text);
const reviewStatus = String(review.status ?? '').toLowerCase();
const reviewScore = Number(review.score ?? 0);
const reviewReason = String(review.reason ?? '');
const reviewNextTask = String(review.next_task ?? '');

return [{
  json: {
    ...$json,
    review,
    review_valid: true,
    review_raw: raw,
    review_status: reviewStatus,
    review_score: reviewScore,
    review_reason: reviewReason,
    review_next_task: reviewNextTask
  }
}];

const base = $('Prepare Current Task').isExecuted
  ? $('Prepare Current Task').last().json
  : $('Restore Saved Task State').last().json;

const nextIndex = Number(base.task_index ?? 0) + 1;
const tasks = Array.isArray(base.tasks) ? base.tasks : [];

if (nextIndex >= tasks.length) {
  return [{
    json: {
      ...base,
      task_index: nextIndex,
      execution_route: 'all_tasks_completed',
      last_review_score: Number($json.review_score ?? 0),
      last_review_reason: String($json.review_reason ?? '')
    }
  }];
}

return [{
  json: {
    ...base,
    task_index: nextIndex,
    task_attempt: 1,
    review_feedback: '',
    execution_route: 'run_task',
    last_review_score: Number($json.review_score ?? 0),
    last_review_reason: String($json.review_reason ?? '')
  }
}];

const base = $('Prepare Current Task').isExecuted
  ? $('Prepare Current Task').last().json
  : $('Restore Saved Task State').last().json;

const currentAttempt = Number(base.task_attempt ?? 1);
const maxAttempts = Number(
  $('Constants').first().json.max_attempts_per_task ?? 3
);

if (currentAttempt >= maxAttempts) {
  return [{
    json: {
      ...base,
      execution_route: 'failed',
      final_status: 'failed_task_attempt_limit',
      failure_reason: String(
        $json.review_reason ?? 'Maximum task attempts reached.'
      ),
      last_review_score: Number($json.review_score ?? 0),
      last_review_reason: String($json.review_reason ?? '')
    }
  }];
}

return [{
  json: {
    ...base,
    task_attempt: currentAttempt + 1,
    review_feedback: String(
      $json.review_next_task ||
      $json.review_reason ||
      ''
    ),
    execution_route: 'run_task',
    last_review_score: Number($json.review_score ?? 0),
    last_review_reason: String($json.review_reason ?? '')
  }
}];

const status = String(
  $json.final_status ||
  $json.reviewer_route ||
  $json.worker_route ||
  $json.architect_route ||
  'failed'
);

const role =
  ($json.reviewer_route || $json.reviewer_status) ? 'reviewer' :
  ($json.worker_route || $json.worker_status) ? 'worker' :
  ($json.architect_route || $json.architect_status) ? 'architect' :
  'task';

const reason = String(
  $json.failure_reason ||
  $json.last_review_reason ||
  $json.hermes_error ||
  $json.error ||
  `Hermes ${role} failed.`
);

return [{ json: { status, role, reason, run_id: String($json.run_id ?? ''), http_error_code: $json.http_error_code ?? null, task_id: String($json.current_task_id ?? ''), task_attempt: Number($json.task_attempt ?? 0), provider_error: String($json.provider_error ?? '') } }];

return [{
  json: {
    status: 'approved',
    plan_summary: String($json.plan_summary ?? ''),
    total_tasks: Number($json.total_tasks ?? 0),
    completed_tasks: Number($json.task_index ?? 0),
    last_task: String($json.current_task_id ?? ''),
    last_review_score: Number($json.last_review_score ?? 0),
    reason: String($json.last_review_reason ?? 'All planned tasks passed independent review.')
  }
}];

const rows = $('Load Prompts').all().map(item => item.json || {});
const result = {};
for (const agent of ['architect','worker','reviewer']) {
  const candidates = rows
    .filter(r => String(r.agent_id ?? '').trim() === agent)
    .filter(r => r.enabled === true || String(r.enabled ?? '').toLowerCase() === 'true')
    .sort((a,b) => Number(b.version ?? 0) - Number(a.version ?? 0));
  if (!candidates.length) throw new Error(`No enabled prompt found for agent '${agent}'.`);
  result[`${agent}_prompt`] = String(candidates[0].system_prompt ?? '').trim();
  if (!result[`${agent}_prompt`]) throw new Error(`Prompt '${agent}' is empty.`);
}
return [{json:result}];

const rows = $('Load Config').all().map(item => item.json || {});
const row = rows.find(r => String(r.profile_id ?? '').trim() === 'default' && (r.enabled === true || String(r.enabled ?? '').toLowerCase() === 'true')) || rows[0];
if (!row) throw new Error('No enabled default Hermes configuration found in Data Table hermes_config.');

function num(value, field, min = 0) {
  const n = Number(value);
  if (!Number.isFinite(n) || n < min) throw new Error(`Invalid ${field}: ${value}`);
  return n;
}

let retryDelays = [15,30,60,120,300];
if (String(row.retry_delays_json ?? '').trim()) {
  try {
    const parsed = JSON.parse(String(row.retry_delays_json));
    if (!Array.isArray(parsed) || parsed.some(v => !Number.isFinite(Number(v)) || Number(v) < 0)) throw new Error('retry_delays_json must be a JSON array of non-negative numbers');
    retryDelays = parsed.map(Number);
  } catch (e) {
    throw new Error(`Invalid retry_delays_json: ${e.message}`);
  }
}

return [{json:{
  planner_model:String(row.architect_model ?? '').trim(),
  planner_provider:String(row.architect_provider ?? '').trim(),
  worker_model:String(row.worker_model ?? '').trim(),
  worker_provider:String(row.worker_provider ?? '').trim(),
  reviewer_model:String(row.reviewer_model ?? '').trim(),
  reviewer_provider:String(row.reviewer_provider ?? '').trim(),
  max_tasks:num(row.max_tasks,'max_tasks',1),
  max_attempts_per_task:num(row.max_attempts_per_task,'max_attempts_per_task',1),
  architect_max_provider_retries:num(row.architect_max_retries,'architect_max_provider_retries',0),
  worker_max_provider_retries:num(row.worker_max_retries,'worker_max_provider_retries',0),
  reviewer_max_provider_retries:num(row.reviewer_max_retries,'reviewer_max_provider_retries',0),
  architect_max_polls:num(row.architect_max_polls,'architect_max_polls',1),
  worker_max_polls:num(row.worker_max_polls,'worker_max_polls',1),
  reviewer_max_polls:num(row.reviewer_max_polls,'reviewer_max_polls',1),
  architect_poll_seconds:num(row.architect_poll_seconds,'architect_poll_seconds',1),
  worker_poll_seconds:num(row.worker_poll_seconds,'worker_poll_seconds',1),
  reviewer_poll_seconds:num(row.reviewer_poll_seconds,'reviewer_poll_seconds',1),
  state_namespace:String(row.state_namespace ?? 'llama.cpp-dashboard-v1'),
  execution_mode:String(row.execution_mode ?? 'production'),
  retry_delays:retryDelays
}}];

