const planText = String($json.plan_json ?? '').trim();

if (!planText) {
  throw new Error('Saved task state contains no plan_json.');
}

let plan;

try {
  plan = JSON.parse(planText);
} catch (error) {
  throw new Error(`Saved task state contains invalid plan_json: ${error.message}`);
}

if (
  !plan ||
  typeof plan !== 'object' ||
  !Array.isArray(plan.tasks) ||
  plan.tasks.length === 0
) {
  throw new Error('Saved task state contains an invalid or empty task plan.');
}

const taskIndex = Number($json.task_index ?? 0);

if (
  !Number.isInteger(taskIndex) ||
  taskIndex < 0 ||
  taskIndex > plan.tasks.length
) {
  throw new Error(`Saved task state contains invalid task_index: ${$json.task_index}`);
}

return [{
  json: {
    plan_summary: String(plan.summary ?? ''),
    tasks: plan.tasks,
    task_index: taskIndex,
    task_attempt: Number($json.task_attempt ?? 1),
    total_tasks: plan.tasks.length,

    review_feedback: String($json.review_feedback ?? ''),
    last_review_score: Number($json.last_review_score ?? 0),
    last_review_reason: String($json.last_review_reason ?? ''),

    reviewer_run_id: String($json.reviewer_run_id ?? ''),
    reviewer_status: String($json.reviewer_status ?? ''),
    reviewer_session_id: String($json.reviewer_session_id ?? ''),

    worker_run_id: String($json.worker_run_id ?? ''),
    worker_status: String($json.worker_status ?? ''),
    worker_session_id: String($json.worker_session_id ?? ''),

    execution_route:
      taskIndex >= plan.tasks.length
        ? 'all_tasks_completed'
        : 'run_task'
  }
}];

return [{
  json: {
    ...$('Restore Plan Context').last().json,
    task_index: 0,
    task_attempt: 1,
    total_tasks: Number($('Parse Plan').first().json.total_tasks ?? $('Parse Plan').first().json.tasks.length),
    review_feedback: '',
    last_review_score: 0,
    last_review_reason: '',
    execution_route: 'run_task'
  }
}];

return [{
  json: {
    ...$('Advance Task').last().json
  }
}];

