const review = $('Parse Review').last().json ?? {};

const state = $('Prepare Current Task').isExecuted
  ? $('Prepare Current Task').last().json
  : ($('Restore Saved Task State').last().json ?? {});

const taskId = String(
  state.current_task_id ??
  state.tasks?.[Number(state.task_index ?? 0)]?.id ??
  ''
);

const reviewMessage = [
  '🧪 REVIEW RESULT',
  `Task: ${taskId}`,
  `Status: ${String(review.review_status ?? '')}`,
  `Score: ${String(review.review_score ?? 0)}`,
  String(review.review_reason ?? ''),
  review.review_next_task
    ? `Next: ${String(review.review_next_task)}`
    : ''
].filter(Boolean).join('\n');

return [{
  json: {
    ...review,
    review_message: reviewMessage
  }
}];

function last(name) {
  try {
    const items = $(name).all();
    return items.length ? items[items.length - 1].json : null;
  } catch (_) {
    return null;
  }
}

const failure = $json;
const current = last('Prepare Current Task');
const parsed = last('Parse Plan');
const saved = last('Load Task State');
const reviewerStart = last('Reviewer Start');

const tasks =
  Array.isArray(current?.tasks) ? current.tasks :
  Array.isArray(parsed?.tasks) ? parsed.tasks :
  [];

const planSummary =
  current?.plan_summary ??
  parsed?.plan_summary ??
  '';

const savedPlan = String(saved?.plan_json ?? '');

return [{
  json: {
    ...failure,

    failure_plan_json: tasks.length
      ? JSON.stringify({
          summary: String(planSummary),
          tasks
        })
      : savedPlan,

    failure_task_index: Number(
      current?.task_index ??
      saved?.task_index ??
      0
    ),

    failure_task_attempt: Number(
      current?.task_attempt ??
      saved?.task_attempt ??
      1
    ),

    failure_review_feedback: String(
      current?.review_feedback ??
      saved?.review_feedback ??
      ''
    ),

    failure_last_review_score: Number(
      current?.last_review_score ??
      saved?.last_review_score ??
      0
    ),

    failure_last_review_reason: String(
      current?.last_review_reason ??
      saved?.last_review_reason ??
      failure.reason ??
      ''
    ),

    failure_reviewer_run_id: String(
      reviewerStart?.run_id ??
      failure.reviewer_run_id ??
      failure.run_id ??
      ''
    ),

    failure_reviewer_session_id: String(
      reviewerStart?.session_id ??
      failure.reviewer_session_id ??
      failure.session_id ??
      ''
    ),

    failure_reviewer_status: String(
      failure.reviewer_status ??
      failure.status ??
      ''
    )
  }
}];

function unwrap(value) { const x = value?.json ?? value?.data ?? value ?? {}; return x && typeof x === 'object' && !Array.isArray(x) ? x : {}; }
const result = unwrap($json);
const status = String(result.status ?? '').toLowerCase();
const route = String(result.route ?? (status === 'completed' ? 'completed' : '')).toLowerCase();
const base=$('Reviewer State').isExecuted?$('Reviewer State').last().json:$('Restore Saved Task State').last().json;
return [{json:{...base,reviewer_run_id:String(result.run_id??''),reviewer_session_id:String(result.session_id??base.reviewer_session_id??''),reviewer_status:status,reviewer_route:route,route: String(result.route ?? result.reviewer_route ?? ''),reviewer_output:String(result.output??result.response??result.content??''),reviewer_session_verified:Boolean(result.session_verified??false),reviewer_session_mismatch:Boolean(result.session_mismatch??false),error:String(result.error??''),error_code:String(result.error_code??'')}}];
